INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Triple Strength Omega-3 Fish Oil', 'Mafuta ya Samaki Omega-3 Ulimwengu', 'Huile de Poisson Oméga-3 Triple Force', 'cardiovascular', 3500, NULL, '90 softgels', 'Vidonge 90', '90 gélules', 'assets/products/01-omega3-fish-oil.webp', 30, 4.8, 22, '["Bestseller"]', 'Highly concentrated essential fatty acids supplying structural EPA and DHA. Maintains vascular elasticity, manages systemic inflammation, lowers triglycerides, and supports cognitive health.', 'Asidi fatty muhimu zenye umakini mkubwa zinazotoa EPA na DHA. Zinadumisha uhimilivu wa mishipa, kusawazisha mfumo wa uvimbe, kupunguza triglycerides, na kuunga mkono afya ya ubongo.', 'Acides gras essentiels hautement concentrés fournissant de l''EPA et du DHA structurels. Maintiennent l''élasticité vasculaire, gèrent l''inflammation systémique, réduisent les triglycérides et soutiennent la santé cognitive.', '["Maintains vascular elasticity","Reduces systemic inflammation","Lowers triglyceride levels","Supports cognitive health"]', '["Inadumisha uhimilivu wa mishipa","Inapunguza mfumo wa uvimbe","Inapunguza viwango vya triglyceride","Inaunga mkono afya ya ubongo"]', '["Maintient l''élasticité vasculaire","Réduit l''inflammation systémique","Abaisse les triglycérides","Soutient la santé cognitive"]', 1);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Aged Garlic Extract', 'Mwanzo wa Gesi Iliondolewa', 'Extrait d''Ail Vieilli', 'cardiovascular', 2800, NULL, '60 capsules', 'Vidonge 60', '60 gélules', 'assets/products/02-aged-garlic-extract.webp', 25, 4.7, 18, '[]', 'An odorless, fermented garlic formulation containing active organosulfur components. Optimizes arterial blood pressure, manages healthy cholesterol profiles, and delivers foundational microbial defenses.', 'Mchanganyiko wa gesi usio na harufu, uliochongwa, unaosherehekea viungo vya organosulfur. Inaboresha shinikizo la damu ya mishipa, kusawazisha viwango vya cholesterol, na kutoa ulinzi wa msingi wa vijidudu.', 'Formulation d''ail fermenté inodore contenant des composés organosoufre actifs. Optimise la pression artérielle, gère les profils de cholestérol sains et fournit des défenses microbiennes fondamentales.', '["Optimizes arterial blood pressure","Manages healthy cholesterol profiles","Odorless fermented formulation","Delivers microbial defenses"]', '["Inaboresha shinikizo la damu ya mishipa","Inasawazisha viwango vya cholesterol","Mchanganyiko usio na harufu","Inatoa ulinzi wa vijidudu"]', '["Optimise la pression artérielle","Gère les profils de cholestérol sains","Formulation fermentée inodore","Fournit des défenses microbiennes"]', 2);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Blood Circulation Flow', 'Mtiririko wa Mzunguko wa Damu', 'Circulation Sanguine', 'cardiovascular', 2200, NULL, '60 tablets', 'Vidonge 60', '60 comprimés', 'assets/products/03-blood-circulation-flow.webp', 20, 4.6, 15, '[]', 'A targeted nutrient and herbal botanical blend designed to promote efficient vascular hemodynamics. Strengthens vein walls and reduces fluid pooling or heaviness in the lower extremities.', 'Mchanganyiko wa virutubisho na mimea yaliyolengwa iliyoundwa kuendeleza mfumo wa damu. Inaimarisha kuta za mishipa na kupunguza maji kwenye viungo vya chini.', 'Mélange ciblé de nutriments et de plantes botaniques conçu pour promouvoir une hémodynamique vasculaire efficace. Renforce les parois veineuses et réduit la stagnation fluidique.', '["Promotes vascular hemodynamics","Strengthens vein walls","Reduces fluid pooling","Targets lower extremities"]', '["Inaendeleza mfumo wa damu wa mishipa","Inaimarisha kuta za mishipa","Inapunguza maji kwenye viungo","Inalenga viungo vya chini"]', '["Promeut l''hémodynamique vasculaire","Renforce les parois veineuses","Réduit la stagnation fluidique","Cible les membres inférieurs"]', 3);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Dried Hawthorn Berries', 'Tunda la Hawthorn Kavu', 'Baies d''Aubépine Séchées', 'cardiovascular', 1800, NULL, '100g loose', '100g huru', '100g en vrac', 'assets/products/04-dried-hawthorn-berries.webp', 18, 4.5, 10, '[]', 'Dehydrated, sliced whole-food berries used traditionally as an infusion or tea. Naturally enhances cardiac muscle contraction efficiency, helps regulate blood pressure, and provides potent antioxidant flavonoids.', 'Matunda yaliyokaushwa, yaliyokatwa kikamilifu, yatumika kwa jadi kama infusioni au chai. Inaongeza ufanisi wa kusinywa kwa misa ya moyo, kusaidia kusawazisha shinikizo la damu, na kutoa flavonoids za antioxidants.', 'Baies entières déshydratées et tranchées utilisées traditionnellement en infusion ou en thé. Améliore naturellement l''efficacité de la contraction du muscle cardiaque, aide à réguler la pression artérielle et fournit des flavonoïdes antioxydants puissants.', '["Enhances cardiac contraction","Regulates blood pressure","Rich in antioxidant flavonoids","Traditional whole-food infusion"]', '["Inaongeza ufanisi wa kusinywa kwa misa ya moyo","Inasawazisha shinikizo la damu","Yenye flavonoids nyingi za antioxidants","Infusioni ya jadi ya matunda kamili"]', '["Améliore la contraction cardiaque","Régule la pression artérielle","Riche en flavonoïdes antioxydants","Infusion traditionnelle à base de baies entières"]', 4);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('N-Acetyl Cysteine (NAC)', 'N-Acetyl Cysteine (NAC)', 'N-Acétyl Cystéine (NAC)', 'cellular', 2500, NULL, '60 capsules', 'Vidonge 60', '60 gélules', 'assets/products/05-nac.webp', 22, 4.8, 16, '["Popular"]', 'A stable sulfur-bearing amino acid that serves as the immediate direct precursor to glutathione. Drives hepatic detoxification pathways, neutralizes heavy metal accumulation, and thins thick respiratory mucus.', 'Asidi amino thabati yenye kiberiti inayotumika kuwa mtangulizi wa moja kwa moja wa glutathione. Inaendesha njia za kusafisha ini, kutengeneza uzito wa chuma, na kufanya mucus ya kupumua kuwa nyeposi.', 'Acide aminé soufré stable servant de précurseur direct immédiat au glutathion. Oriente les voies de détoxification hépatique, neutralise l''accumulation de métaux lourds et fluidifie le mucus respiratoire épais.', '["Precursor to glutathione synthesis","Drives hepatic detoxification","Neutralizes heavy metal accumulation","Thins respiratory mucus"]', '["Mtangulizi wa glutathione","Inaendesha njia za kusafisha ini","Inatengeneza uzito wa chuma","Inafanya mucus ya kupumua kuwa nyeposi"]', '["Précurseur de la synthèse du glutathion","Oriente la détoxification hépatique","Neutralise l''accumulation de métaux lourds","Fluidifie le mucus respiratoire"]', 5);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Selenium 200mcg', 'Selenium 200mcg', 'Sélénium 200mcg', 'cellular', 1500, NULL, '60 tablets', 'Vidonge 60', '60 comprimés', 'assets/products/06-selenium.webp', 28, 4.7, 12, '[]', 'An essential trace mineral acting as a crucial cofactor for the enzyme glutathione peroxidase. Directly protects cells against oxidative damage, maintains thyroid hormone conversions, and primes immune response cycles.', 'Madini muhimu yanayotumika kuwa msaidizi muhimu wa enzyme ya glutathione peroxidase. Inalinda seli dhidi ya uharibifu wa oksidishaji, kusawazisha mabadiliko ya homoni za thyroid, na kuandaa mizunguko ya mwitikio wa kinga.', 'Oligo-élément essentiel agissant comme cofacteur crucial pour l''enzyme glutathion peroxydase. Protège directement les cellules contre les dommages oxydatifs, maintient les conversions hormonales thyroïdiennes et prépare les cycles de réponse immunitaire.', '["Cofactor for glutathione peroxidase","Protects cells from oxidative damage","Maintains thyroid hormone conversions","Primes immune response cycles"]', '["Msaidizi wa glutathione peroxidase","Inalinda seli dhidi ya uharibifu","Kusawazisha mabadiliko ya homoni za thyroid","Kuandaa mizunguko ya mwitikio wa kinga"]', '["Cofacteur pour glutathion peroxydase","Protège les cellules des dommages oxydatifs","Maintient les conversions hormonales thyroïdiennes","Prépare les cycles de réponse immunitaire"]', 6);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Sugar Balance & Chromium Picolinate', 'Usawa wa Sukari na Chromium Picolinate', 'Équilibre Sucre & Picolinate de Chrome', 'cellular', 2800, NULL, '60 capsules', 'Vidonge 60', '60 gélules', 'assets/products/07-sugar-balance.webp', 20, 4.6, 14, '[]', 'A synergy of trace minerals and active bitter herbs formulated to modulate peripheral insulin receptor sensitivity. Assists the body in processing dietary carbohydrates and stabilizes fluctuating blood glucose curves.', 'Umoja wa madini midogo na mimea chungu hai iliyoundwa kurekebisha unyeti wa receptors za insulini. Inasaidia mwili kuchakata carbs za chakula na kusawazisha viwango vya glucose vya damu.', 'Synergie d''oligo-éléments et d''herbes amères actives formulée pour moduler la sensibilité des récepteurs insuliniques périphériques. Aide le corps à traiter les glucides alimentaires et stabilise les courbes glycémiques fluctuantes.', '["Modulates insulin receptor sensitivity","Assists carbohydrate processing","Stabilizes blood glucose curves","Trace mineral synergy"]', '["Kurekebisha unyeti wa receptors za insulini","Kusaidia uchakataji wa carbs","Kusawazisha viwango vya glucose","Umoja wa madini midogo"]', '["Module la sensibilité des récepteurs insuliniques","Aide au traitement des glucides","Stabilise les courbes glycémiques","Synergie d''oligo-éléments"]', 7);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Calcium Magnesium Zinc + D3', 'Calcium Magnesium Zinc + D3', 'Calcium Magnésium Zinc + D3', 'skeletal', 2200, NULL, '120 tablets', 'Vidonge 120', '120 comprimés', 'assets/products/08-cal-mag-zinc-d3.webp', 25, 4.7, 20, '["Popular"]', 'A structural multi-mineral matrix reinforced with fat-soluble vitamin D3. Optimizes bone mineralization, regulates muscular contraction-relaxation cycles, and sustains cellular immune actions.', 'Matriks ya madini mingi iliyoimarishwa na vitamini D3 yenye mafuta. Inaboresha usanisinuru wa mifupa, kusawazisha mizunguko ya kusinywa-kulegea kwa misa, na kuendeleza vitendo vya kinga vya seli.', 'Matrice multi-minérale structurelle renforcée par la vitamine D3 liposoluble. Optimise la minéralisation osseuse, régule les cycles de contraction-relaxation musculaire et maintient les actions immunitaires cellulaires.', '["Optimizes bone mineralization","Reinforced with vitamin D3","Regulates muscle contraction cycles","Sustains cellular immune actions"]', '["Inaboresha usanisinuru wa mifupa","Imeimarishwa na vitamini D3","Kusawazisha mizunguko ya kusinywa kwa misa","Kuendeleza vitendo vya kinga vya seli"]', '["Optimise la minéralisation osseuse","Renforcée avec la vitamine D3","Régule les cycles de contraction musculaire","Maintient les actions immunitaires cellulaires"]', 8);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Triple Magnesium Complex', 'Magnesium Complex ya Mara Tatu', 'Complexe Magnésium Triple', 'skeletal', 2400, NULL, '60 capsules', 'Vidonge 60', '60 gélules', 'assets/products/09-triple-magnesium.webp', 22, 4.8, 16, '[]', 'A combined formulation containing multiple bioavailable delivery vectors of elemental magnesium. Works deeply to soothe neuromuscular hyperactivity, ease muscle cramps, and promote deep nervous system relaxation.', 'Mchanganyiko unaovecta za uwasilishaji nyingi za magnesium ya elementi. Inafanya kazi kwa kina kupunguza shughuli nyingi za neuromuscular, kulegea krama za misa, na kukuza upole wa mfumo wa neva.', 'Formulation combinée contenant plusieurs vecteurs de livrance bioavailables de magnésium élémentaire. Agit en profondeur pour apaiser l''hyperactivité neuromusculaire, soulager les crampes musculaires et favoriser la relaxation profonde du système nerveux.', '["Multiple bioavailable delivery vectors","Soothes neuromuscular hyperactivity","Eases muscle cramps","Promotes nervous system relaxation"]', '["Za uwasilishaji nyingi za magnesium","Kupunguza shughuli za neuromuscular","Kulegea krama za misa","Kukuza upole wa mfumo wa neva"]', '["Vecteurs de livrance bioavailables multiples","Apaise l''hyperactivité neuromusculaire","Soulage les crampes musculaires","Favorise la relaxation du système nerveux"]', 9);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('High Potency Zinc (50mg)', 'Zinc ya Uwiano wa Juu (50mg)', 'Zinc Haute Puissance (50mg)', 'skeletal', 1200, NULL, '60 tablets', 'Vidonge 60', '60 comprimés', 'assets/products/10-zinc-50mg.webp', 30, 4.6, 18, '["Bestseller"]', 'An isolated trace mineral supplement serving as an enzymatic catalyst for hundreds of internal biological processes. Accelerates wound healing, builds T-lymphocytes, and blocks viral replication cycles.', 'Madini madogo yaliyotengwa yanayotumika kuwa katalysti ya enzyme kwa mchakato wa biolojia ndani. Inaharakisha uponyaji vidonda, kujenga T-lymphocytes, na kuzuia mizunguko ya ulipukaji wa virusi.', 'Supplément d''oligo-élément isolé servant de catalyseur enzymatique pour des centaines de processus biologiques internes. Accélère la cicatrisation des plaies, construit les lymphocytes T et bloque les cycles de réplication virale.', '["Enzymatic catalyst for biological processes","Accelerates wound healing","Builds T-lymphocytes","Blocks viral replication cycles"]', '["Katalysti ya enzyme kwa mchakato wa biolojia","Kuharakisha uponyaji vidonda","Kujenga T-lymphocytes","Kuzuia mizunguko ya ulipukaji wa virusi"]', '["Catalyseur enzymatique pour les processus biologiques","Accélère la cicatrisation des plaies","Construit les lymphocytes T","Bloque les cycles de réplication virale"]', 10);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Lion''s Mane Liquid Extract', 'Mwanzo wa Maji ya Uzi wa Simba', 'Extrait Liquide Lion de la Mane', 'neurological', 4500, NULL, '60ml tincture', 'Dawa 60ml', '60ml teinture', 'assets/products/11-lions-mane.webp', 15, 4.9, 14, '["Premium"]', 'A concentrated liquid extract from Hericium erinaceus fruiting bodies. Stimulates natural Neural Growth Factor (NGF) synthesis, enhancing memory retention, analytical focus, and myelin sheath structural integrity.', 'Mwanzo wa maji uliokusanywa kutoka kwa matunda ya Hericium erinaceus. Inachochea utengenezaji wa Neural Growth Factor (NGF), kuboresha kumbukumbu, uchambuzi, na uhimilivu wa myelin sheath.', 'Extrait liquide concentré provenant des fruiting bodies d''Hericium erinaceus. Stimule la synthèse naturelle du Neural Growth Factor (NGF), améliore la rétention mnésique, la concentration analytique et l''intégrité structurelle de la gaine de myéline.', '["Stimulates NGF synthesis","Enhances memory retention","Improves analytical focus","Supports myelin sheath integrity"]', '["Inachochea utengenezaji wa NGF","Kuboresha kumbukumbu","Kuboresha uchambuzi","Kusaidia uhimilivu wa myelin sheath"]', '["Stimule la synthèse du NGF","Améliore la rétention mnésique","Améliore la concentration analytique","Soutient l''intégrité de la gaine de myéline"]', 11);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Rhodiola Rosea', 'Rhodiola Rosea', 'Rhodiola Rosea', 'neurological', 3200, NULL, '60 capsules', 'Vidonge 60', '60 gélules', 'assets/products/12-rhodiola-rosea.webp', 18, 4.7, 11, '[]', 'A cold-climate adaptogenic root extract standardized for active rosavins and salidrosides. Helps the adrenal system balance sustained stress, mitigates mental burnout, and stabilizes physical performance.', 'Mwanzo wa mizizi ya adaptogenic ya baridi uliochaguliwa kwa rosavins na salidrosides hai. Inasaidia mfumo wa adrenal kusawazisha msongo endelevu, kupunguza uchovu wa akili, na kusawazisha utendaji wa mwili.', 'Extrait de racine adaptogène de climat froid standardisé pour les rosavins et salidroside actifs. Aide le système surrénal à équilibrer le stress soutenu, atténue l''épuisement mental et stabilise les performances physiques.', '["Standardized rosavins and salidrosides","Balances sustained stress","Mitigates mental burnout","Stabilizes physical performance"]', '["Rosavins na salidrosides","Kusawazisha msongo endelevu","Kupunguza uchovu wa akili","Kusawazisha utendaji wa mwili"]', '["Rosavins et salidroside standardisés","Équilibre le stress soutenu","Atténue l''épuisement mental","Stabilise les performances physiques"]', 12);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Shilajit Complex', 'Mchanganyiko wa Shilajit', 'Complexe Shilajit', 'neurological', 5500, NULL, '60 capsules', 'Vidonge 60', '60 gélules', 'assets/products/13-shilajit-complex.webp', 12, 4.8, 9, '["Premium"]', 'A mineral-dense fulvic acid resin compound combined with ashwagandha and ginseng roots. Facilitates direct mitochondrial ATP energy production, raises physical stamina, and combats long-term biological fatigue.', 'Muundo wa asidi ya fulvic yenye madini mengi uliochanganywa na mizizi ya ashwagandha na ginseng. Inarahisisha utengenezaji wa ATP ya mitochondria, kuongeza ustahimilivu wa mwili, na kupigana na uchovu wa biolojia wa muda mrefu.', 'Composé de résine d''acide fulvique riche en minéraux combiné avec des racines d''ashwagandha et de ginseng. Facilite la production directe d''ATP mitochondrial, augmente l''endurance physique et combat la fatigue biologique à long terme.', '["Facilitates mitochondrial ATP production","Combined with ashwagandha and ginseng","Raises physical stamina","Combats long-term fatigue"]', '["Inarahisisha utengenezaji wa ATP ya mitochondria","Imechanganywa na ashwagandha na ginseng","Kuongeza ustahimilivu wa mwili","Kupigana na uchovu wa muda mrefu"]', '["Facilite la production d''ATP mitochondrial","Combiné avec ashwagandha et ginseng","Augmente l''endurance physique","Combat la fatigue à long terme"]', 13);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Myo & D-Chiro Inositol', 'Myo & D-Chiro Inositol', 'Myo & D-Chiro Inositol', 'womens', 3800, NULL, '60 sachets', 'Mifuko 60', '60 sachets', 'assets/products/14-inositol-40-1.webp', 16, 4.8, 12, '["New"]', 'A specialized carbohydrate isomer formulation prepared in a clinically validated 40:1 ratio. Primarily utilized to restore proper ovarian function, regulate menstrual timelines, and manage insulin dynamics in women with PCOS.', 'Mchanganyiko wa carbohydrate isomer maalum uliotengenezwa kwa uwiano wa 40:1 uliothibitishwa kliniki. Unatumika hasa kurejesha utendaji sahihi wa ovari, kusawazisha muda wa hedhi, na kusawazisha dynamics za insulini kwa wanawake wenye PCOS.', 'Formulation spécialisée d''isomères de glucides préparée dans un ratio 40:1 cliniquement validé. Utilisée principalement pour restaurer la fonction ovarienne appropriée, réguler les cycles menstruels et gérer la dynamique insulinique chez les femmes atteintes de SOPK.', '["Clinically validated 40:1 ratio","Restores ovarian function","Regulates menstrual timelines","Manages insulin dynamics in PCOS"]', '["Uwiano wa 40:1 uliothibitishwa kliniki","Kurejesha utendaji wa ovari","Kusawazisha muda wa hedhi","Kusawazisha dynamics za insulini kwa PCOS"]', '["Ratio 40:1 cliniquement validé","Restaure la fonction ovarienne","Régule les cycles menstruels","Gère la dynamique insulinique dans le SOPK"]', 14);
INSERT INTO products (name_en, name_sw, name_fr, category, price, original_price, unit_en, unit_sw, unit_fr, image_url, stock, rating, review_count, badges, desc_en, desc_sw, desc_fr, benefits_en, benefits_sw, benefits_fr, sort_order) VALUES ('Women''s Probiotic & Vaginal Health Gummies', 'Probiotic za Wanawake na Viatu vya Afya ya Vagina', 'Probiotiques Féminins & Pastilles Santé Vaginale', 'womens', 2600, NULL, '60 gummies', 'Viatu 60', '60 pastilles', 'assets/products/15-womens-probiotic.webp', 18, 4.7, 10, '["New"]', 'Targeted, acid-resistant active bacterial strains delivering beneficial microbes to the reproductive tract. Prevents colonization of pathogenic bacteria and maintains a balanced internal pH environment.', 'Aina za bakteria zilizolengwa, zinazostahimili asidi, zinazopeleka vijidudu vyenye manufaa kwa njia ya uzazi. Inazuia uenezi wa bakteria hatari na kudumisha mazingira ya pH ya ndani.', 'Souches bactériennes actives ciblées, résistantes à l''acidité, délivrant des micro-organismes bénéfiques au tractus reproducteur. Prévient la colonisation de bactéries pathogènes et maintient un environnement pH interne équilibré.', '["Acid-resistant bacterial strains","Delivers beneficial microbes to reproductive tract","Prevents pathogenic colonization","Maintains balanced internal pH"]', '["Aina za bakteria zinazostahimili asidi","Kupeleka vijidudu vyenye manufaa kwa njia ya uzazi","Kuzuia uenezi wa bakteria hatari","Kudumisha mazingira ya pH ya ndani"]', '["Souches bactériennes résistantes à l''acidité","Délivrent des micro-organismes bénéfiques au tractus reproducteur","Prévient la colonisation pathogène","Maintient un pH interne équilibré"]', 15);
